cte_path:
WITH c_cols AS (
    SELECT ss.cds, ss.`AvgScrMath`, ss.`AvgScrRead`, ss.`AvgScrWrite`, sc.`County`
    FROM satscores AS ss
    INNER JOIN schools AS sc ON ss.cds = sc.`CDSCode`
)
SELECT * FROM c_cols;

WITH c_rows AS (
    SELECT cds, `AvgScrMath`, `AvgScrRead`, `AvgScrWrite`, `County`
    FROM c_cols
    WHERE `AvgScrMath` IS NOT NULL AND `AvgScrRead` IS NOT NULL AND `AvgScrWrite` IS NOT NULL
)
SELECT * FROM c_rows;

WITH t_agg AS (
    SELECT cds, AVG(`AvgScrMath` + `AvgScrRead` + `AvgScrWrite`) AS avg_total_score
    FROM c_rows
    GROUP BY cds
)
SELECT * FROM t_agg;

WITH t_final AS (
    SELECT t_min.cds, t_min.avg_total_score, sc.`County`
    FROM t_min
    INNER JOIN schools AS sc ON t_min.cds = sc.`CDSCode`
)
SELECT * FROM t_final;

WITH final_answer AS (
    SELECT avg_total_score, `County`
    FROM t_final
)
SELECT * FROM final_answer;

